import{_ as s,l as n,o as e,c as o,v as t,p as l,x as i,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"高斯消元与线性基","description":"","frontmatter":{"title":"高斯消元与线性基","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gaussian-elimination-xor-basis.md","filePath":"cs/gaussian-elimination-xor-basis.md","lastUpdated":1789023840000}'),m={name:"cs/gaussian-elimination-xor-basis.md"};function c(_,a,u,b,E,f){const r=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="高斯消元与线性基" tabindex="-1">高斯消元与线性基 <a class="header-anchor" href="#高斯消元与线性基" aria-label="Permalink to &quot;高斯消元与线性基&quot;">​</a></h1><div class="epigraph"><p>行变换把矩阵变成阶梯：解线性方程组、求秩；$\\mathrm{GF}(2)$ 上同一过程给出线性基，能插、能问最大异或。</p><footer>—— 据 CLRS 第 28 章；线性基为竞赛与编码教材标准技法整理</footer></div><p>上一课<a href="/cs/strassen">Strassen</a>谈乘的渐近。解 \\(Ax=b\\) 要消元，不是乘。缺口是高斯消元：\\(O(n^3)\\) 行操作，以及 \\(\\mathbb{F}_2\\) 上把向量插入基。不重写矩阵幂。后课单纯形在不等式上走顶点。接<a href="/cs/finite-field-gf2n">有限域</a>只当系数域，不重写不可约多项式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>域上 \\(n\\times n\\)：选主元，消列，回代。秩、行列式（对角积）、逆（增广单位阵）同一套。无主元则奇异。数值上要选主元抗舍入。\\(\\mathrm{GF}(2)\\)：加即异或，插入：从高位扫，有主元则异或掉，否则占坑。询问：贪心从高位能否变大。</p><p>缺口是行空间基底，不是最大流。</p><h3 id="线性基不是最小生成树" tabindex="-1">线性基不是最小生成树 <a class="header-anchor" href="#线性基不是最小生成树" aria-label="Permalink to &quot;线性基不是最小生成树&quot;">​</a></h3><p>都「插入不相关的」，但一个在向量空间，一个在图切分。不要用并查集当异或基。</p><p><span class="marginnote">CLRS 28 高斯。主元选择见数值分析（Golub–Van Loan 点名）。线性基是高斯在 \\(\\mathbb{F}_2\\) 的在线形式。后课 LP 的可行域不是线性方程组。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方程组：消元 + 回代，\\(O(n^3)\\)。多组 \\(b\\) 可一起。线性基：最多 \\(w\\) 个主元（位宽 \\(w\\)），插入 \\(O(w^2)\\) 或 \\(O(w)\\) 视实现。</p>',11)),(e(),l(p,null,{default:i(()=>[h(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%9F%A9%E9%98%B5%20A%22%5D%20--%3E%20GE%5B%22%E9%80%89%E4%B8%BB%E5%85%83%E6%B6%88%E5%85%83%22%5D%0A%20%20GE%20--%3E%20RREF%5B%22%E9%98%B6%E6%A2%AF%20%2F%20%E7%A7%A9%22%5D%0A%20%20F2%5B%22GF(2)%20%E5%90%91%E9%87%8F%22%5D%20--%3E%20BASIS%5B%22%E9%AB%98%E4%BD%8D%E4%B8%BB%E5%85%83%E5%9F%BA%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>模 \\(p\\) 消元用逆；模合数不是域。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>行变换不改变解集（或改已知的等价）。\\(\\mathbb{F}_2\\) 上线性无关 = 不能异或出零的非空子集。最大异或是基向量按位贪心，正确因高位确定后低位正交补。与高斯：\\(n\\) 个向量插入即消元过程。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 SVD、不写病态数全文。稀疏消元填入另论。后课默认：域上线性方程组高斯；\\(F_2\\) 线性基在线。下一课单纯形：不等式与目标。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>高斯：\\(O(n^3)\\) 解方程、求秩。</li><li>\\(\\mathrm{GF}(2)\\) 线性基插入与最大异或。</li><li>要域；选主元为数值。</li><li>出处：CLRS 第 28 章。</li></ul>',7))])}const x=s(m,[["render",c]]);export{A as __pageData,x as default};
